        self._total = 1

    def add(self, n: int) -> None:
        self._total *= n

    def total(self) -> int:
        return self._total

    def close(self) -> int:
        closing = self._total
        self._total = 1
        return closing

class Session:
    def __init__(self) -> None:
        self._total = 0
        self._closed = False

    def add(self, n: int) -> None:
        if self._closed:
            self._total = 0
            self._closed = False
        self._total += n

    def total(self) -> int:
        return self._total

    def close(self) -> int:
        self._closed = True
        return self._total
